-- 12. 同步冗余计数
UPDATE `author` a SET `album_count` = (SELECT COUNT(*) FROM `album` al WHERE al.`author_id` = a.`id` AND al.`status` = 'published' AND al.`is_deleted` = 0);
UPDATE `author` a SET `last_update_at` = (SELECT MAX(al.`published_at`) FROM `album` al WHERE al.`author_id` = a.`id` AND al.`status` = 'published' AND al.`is_deleted` = 0);
UPDATE `tag` t SET `use_count` = (SELECT COUNT(*) FROM `album_tag` at JOIN `album` a ON a.`id` = at.`album_id` AND a.`status` = 'published' AND a.`is_deleted` = 0 WHERE at.`tag_id` = t.`id`);
UPDATE `album` a SET `comment_count` = (SELECT COUNT(*) FROM `comment` c WHERE c.`album_id` = a.`id` AND c.`status` = 'approved' AND c.`is_deleted` = 0);

